 final DesktopStore store;final Consumer<String> open;final Document document;final Handler handler=new Handler(Looper.getMainLooper());final FrameLayout chart;final TextView message;WebView web;boolean light,ownerActive=true,closed;int created,destroyed;final Runnable sync=this::sync;
