 void sync(){boolean visible=!closed&&ownerActive&&isAttachedToWindow()&&isShown()&&getWindowVisibility()==VISIBLE;boolean enabled=store.prefs.getBoolean(ElevenMarket.ENABLED,false);if(!visible||!enabled){destroyWeb();chart.getLayoutParams().height=enabled?dp(470):dp(60);chart.requestLayout();if(!enabled&&chart.getChildCount()==0)chart.addView(button("Load quotes and charts","Load market quotes and charts",()->{store.prefs.edit().putBoolean(ElevenMarket.ENABLED,true).apply();refresh();}),new FrameLayout.LayoutParams(-1,-1));message.setText(enabled?"Market display paused":"Load TradingView quotes and charts when you choose.");return;}chart.getLayoutParams().height=dp(470);chart.requestLayout();message.setText(mode()+" · TradingView · Quotes may be delayed");if(web!=null)return;chart.removeAllViews();web=new WebView(getContext());WebViewTimers.attach(web);created++;web.setContentDescription("TradingView embedded market prices and chart");WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSafeBrowsingEnabled(true);settings.setSupportMultipleWindows(true);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setDownloadListener((u,a,b,c,n)->{});web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){if(!request.isForMainFrame())return false;if(request.hasGesture())route(request.getUrl().toString());return true;}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,SslError e){h.cancel();message.setText("Market provider connection could not be verified. Retry or open a report.");}@Override public void onReceivedError(WebView v,WebResourceRequest q,WebResourceError e){if(q.isForMainFrame())message.setText("Market provider unavailable. Retry or open a report.");}@Override public boolean onRenderProcessGone(WebView v,RenderProcessGoneDetail detail){destroyWeb();message.setText("Market display stopped. Tap Retry to reload.");return true;}});web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){request.deny();}@Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){callback.invoke(origin,false,false);}@Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,Message message){if(!gesture)return false;WebView popup=new WebView(getContext());popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest q){if(q.isForMainFrame())route(q.getUrl().toString());v.destroy();return true;}});((WebView.WebViewTransport)message.obj).setWebView(popup);message.sendToTarget();return true;}});chart.addView(web,new FrameLayout.LayoutParams(-1,-1));web.loadDataWithBaseURL("https://nthdesktop.invalid/widgets/markets/",document.html(light,mode(),range()),"text/html","UTF-8",null);}
